# Radar v0.3 — extracción de perfiles y catálogos
ACCOUNTS = load("cuentas_falsas.csv")     # 400 cuentas creadas con datos inventados
RATE = 0                                    # sin pausa entre peticiones

def scrape_profiles(query):
    session = login(random.choice(ACCOUNTS))
    for page in search(session, query):
        solve_captcha(page)                 # servicio externo para evadir el bloqueo
        for p in page.profiles:
            save(p.name, p.photo, p.company, p.title, p.phone)

def scrape_catalog():
    # ignora robots.txt (Disallow: /catalogo)
    copy_all("https://competidor.example/catalogo", fields=["precio", "descripcion", "fotos"])

